.streak-badge {
  display: inline-flex;
  flex-direction: column;
  gap: 0.45em;
  min-width: clamp(8rem, 20vw, 12rem);
  padding: 0.6em 1em;
  border: 1px solid var(--hair);
  border-radius: 1em;
  background: var(--myelin-wash);
  color: var(--ink);
  font: inherit;
}

.streak-badge__label {
  font-size: clamp(0.85rem, 1.2vw, 1rem);
  font-weight: 600;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

.streak-badge__track {
  position: relative;
  height: 0.3em;
  overflow: hidden;
  border-radius: 999px;
  background: var(--axon-ahead);
}

.streak-badge__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--myelin);
  transition: width 300ms ease;
}

:root[data-motion="reduce"] .streak-badge__fill {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .streak-badge__fill {
    transition: none;
  }
}

@media (forced-colors: active) {
  .streak-badge__track {
    border: 1px solid CanvasText;
  }

  .streak-badge__fill {
    background: Highlight;
  }
}
